const articles: Record<string, Article> = {
  "surgical-oncology-consultation": {
    title: "Understanding a Surgical Oncology Consultation",
    category: "Surgical Oncology",
    excerpt: "Learn what to expect at a surgical oncology appointment, which medical records to bring and what questions to ask your cancer surgeon in Lahore.",
    intro: "A surgical oncology consultation is an appointment with a surgeon who specialises in assessing cancer-related conditions and the possible role of surgery in treatment. The surgeon reviews your symptoms, medical history, biopsy or histopathology reports, imaging and previous treatment to understand your situation and discuss appropriate next steps. An appointment does not automatically mean that an operation is required.",
    cover: "/images/file_00000000302c8211976d7af899c2483d.png",
    sections: [
      { heading: "What Is a Surgical Oncology Consultation?", paragraphs: ["A surgical oncology consultation is a specialist appointment to assess a suspected or confirmed cancer diagnosis and discuss whether surgery may have a role in management. The surgeon considers the diagnosis, location and extent of the disease, available test results and the patient's overall health.", "Depending on the condition, the discussion may include further investigations, surgical options, other cancer treatments or referral to additional specialists. The purpose is to help you understand the available information and the decisions that may need to be made."] },
      { heading: "How Is a Surgical Oncologist Different From Other Cancer Specialists?", paragraphs: ["Cancer care may involve several specialists who contribute different expertise. They often work together as part of a multidisciplinary team."], bullets: ["Surgical oncologist: assesses the role of surgery in cancer management and discusses surgical options where appropriate.", "Medical oncologist: specialises in systemic treatments such as chemotherapy, immunotherapy and targeted medicines.", "Radiation oncologist: specialises in radiation therapy.", "Radiologist: interprets imaging such as ultrasound, CT, MRI and PET scans.", "Pathologist: examines tissue and cell samples to help establish a diagnosis and identify relevant tumour characteristics."] },
      { heading: "When Should You Consider a Surgical Oncology Consultation?", paragraphs: ["A consultation may be useful at different stages of assessment and treatment. You may be referred after a biopsy or histopathology report, following a suspicious scan or examination, when surgery is being considered, or when you would like another specialist opinion about a proposed surgical approach.", "You do not need to wait until every investigation has been completed before asking for medical advice. If you have a concerning result, contact a qualified healthcare professional to discuss the appropriate next step."] },
      { heading: "What Does a Surgical Oncologist Review During the Consultation?", paragraphs: ["The surgeon considers more than one test result. Your symptoms, medical history, examination findings, pathology, imaging and previous treatment may all contribute to the assessment."] },
      { heading: "1. Your Symptoms and Medical History", paragraphs: ["The surgeon may ask when your symptoms began, how they have changed, what previous illnesses or operations you have had, which medicines you take and whether you have known allergies or relevant family medical history. Explain your concerns clearly, including symptoms that may seem unrelated."] },
      { heading: "2. Biopsy and Histopathology Reports", paragraphs: ["A biopsy involves taking a tissue sample for laboratory examination. A histopathology report describes what the pathologist sees when examining the tissue. Depending on the condition, it may provide information about the type of tumour and characteristics relevant to treatment planning.", "Bring the complete report and any additional pathology or biomarker results that have been performed. The surgeon may need to consider these findings alongside your imaging and clinical information."] },
      { heading: "3. Imaging and Scan Results", paragraphs: ["Imaging can help the medical team understand the location and extent of a disease. Relevant investigations may include ultrasound, CT, MRI or PET/CT, depending on the suspected cancer and the clinical question.", "Where possible, bring both the written radiology report and the actual scan images or digital access details supplied by the imaging centre. A report alone may not contain all the information needed for a specialist review."] },
      { heading: "4. Previous Treatment and General Health", paragraphs: ["If you have already received treatment, the surgeon may ask about the type of treatment, dates and documented response. Previous operation notes, discharge summaries, chemotherapy records and radiotherapy details may be useful.", "Your general health, other medical conditions and current medicines may influence which treatment approaches can reasonably be discussed."] },
      { heading: "What Happens During a Surgical Oncology Appointment?", paragraphs: ["Every consultation is different, but a first appointment commonly includes several stages."] , bullets: ["Discussion of your concerns: the surgeon asks about symptoms, diagnosis and medical history.", "Review of medical records: available pathology reports, scans, blood investigations and previous treatment records are considered.", "Clinical assessment: a physical examination may be appropriate depending on the condition and information available.", "Explanation of findings: the surgeon explains what the reports and examination indicate and identifies any remaining questions.", "Discussion of options: if surgery is relevant, the surgeon may explain its purpose, possible approaches, risks and alternatives.", "Planning next steps: recommendations may include further tests, another specialist opinion, team discussion or follow-up."] },
      { heading: "Which Medical Records Should You Bring?", paragraphs: ["Organising your reports before the appointment can help the surgeon review your history more efficiently. Bring original reports or clear copies where possible, and arrange them in date order."] , bullets: ["Biopsy or histopathology report, including any additional pathology or biomarker results.", "CT, MRI, ultrasound or PET scan reports and the actual images or digital access details.", "Previous operation notes and hospital discharge summaries.", "Details of chemotherapy, radiotherapy or other cancer treatment already received.", "Recent blood investigation results relevant to your condition.", "A current list of prescription medicines, supplements and known allergies.", "A short timeline of symptoms, previous diagnoses and treatment."] },
      { heading: "Important Questions to Ask Your Surgical Oncologist", paragraphs: ["Cancer-related appointments can involve unfamiliar terms and several decisions. Writing down your questions beforehand may help you remember the points that matter most."], bullets: ["What does my biopsy or histopathology report show?", "What is currently known about the extent of the disease?", "Do I need additional tests before a treatment decision?", "Is surgery a possible option in my situation?", "What would be the purpose of the proposed operation?", "Are there other treatment approaches that should be considered?", "What are the potential benefits, risks and limitations of surgery?", "Should another cancer specialist be involved?", "What further information is needed before a decision is made?", "When should I return for follow-up?"] },
      { heading: "How Are Cancer Treatment Decisions Made?", paragraphs: ["Cancer treatment decisions depend on the individual diagnosis and the available clinical evidence. The team may consider the type and characteristics of the cancer, its location and extent, pathology and imaging findings, previous treatment, general health, potential benefits and risks, and the patient's preferences and priorities.", "Depending on the case, a multidisciplinary team may discuss the findings. This can involve surgical oncology, medical oncology, radiation oncology, radiology and pathology. A recommendation should be explained in the context of the patient's individual circumstances."] },
      { heading: "Can You Seek a Second Opinion From a Surgical Oncologist?", paragraphs: ["Yes. A second opinion can be considered when you want another qualified specialist to review your diagnosis, reports or proposed treatment approach. Patients may seek another opinion to clarify a biopsy or imaging result, understand a proposed operation, discuss other management approaches or obtain further perspective on a complex diagnosis.", "For a useful second opinion, take copies of the original pathology reports, scan images, previous operation records and treatment summaries. A second opinion does not automatically mean that the first recommendation was incorrect; it is an opportunity to obtain additional information."] },
      { heading: "What Are the Limitations of a Surgical Oncology Consultation?", paragraphs: ["A consultation helps the surgeon understand the available information, but it cannot guarantee a particular diagnosis, treatment outcome or recovery. An initial appointment may not provide a final treatment plan if additional investigations, pathology review, examination or multidisciplinary discussion are needed.", "A remote review of reports may also have limitations when a physical examination or further testing is clinically necessary. The surgeon may recommend an in-person assessment. Continue to follow advice from your treating healthcare team and seek timely medical attention for urgent or rapidly worsening symptoms."] },
      { heading: "Preparing for a Surgical Oncology Consultation in Lahore", paragraphs: ["Before attending, keep your medical records together and arrange them in date order where possible. Bring pathology reports, scan reports and images, previous treatment details and a current medicine list. Contact the clinic before travelling to confirm the appointment schedule and location.", "Dr. Zain Tayyab Abbas provides surgical oncology consultation information for patients in Lahore. You can review the [Surgical Oncology service](/specialties/surgical-oncology), check [clinic locations](/clinics) and [contact the clinic](/contact) to confirm appointment details."] }
    ],
    faqs: [
      { question: "What is the purpose of a surgical oncology consultation?", answer: "It helps assess a cancer-related condition and discuss whether surgery may have a role in management. The surgeon reviews the diagnosis, reports, symptoms and general health before discussing possible next steps." },
      { question: "Do I need a biopsy report before seeing a surgical oncologist?", answer: "A biopsy report is useful when one has already been performed, but not every consultation requires a completed biopsy. The surgeon can advise which investigations are appropriate based on the reason for referral." },
      { question: "Should I bring the actual CT or MRI images?", answer: "Yes, if they are available. Bring the written report and the actual images or digital access details supplied by the imaging centre. Both may help the specialist review the findings." },
      { question: "Does a surgical oncology consultation mean I need an operation?", answer: "No. A consultation does not automatically mean surgery is necessary. The surgeon assesses whether an operation is appropriate and discusses other relevant options or further investigations." },
      { question: "Can I get a second opinion about cancer surgery?", answer: "Yes. You can request another qualified specialist's opinion about your diagnosis, reports and proposed surgical approach. Bring your original medical records and previous treatment details." },
      { question: "Will the surgeon decide my treatment during the first appointment?", answer: "Not always. Additional investigations, pathology review or multidisciplinary discussion may be required before a final plan is established." },
      { question: "Can a surgical oncologist work with other cancer specialists?", answer: "Yes. Cancer management may involve a multidisciplinary team, including medical oncologists, radiation oncologists, radiologists and pathologists. The specialists involved depend on the patient's condition." },
      { question: "What if I do not have all my medical reports?", answer: "You can still contact the clinic and ask about arranging an appointment. Explain which tests you have completed and where they were performed. The clinic can advise which records to obtain." },
      { question: "How should I prepare for my first appointment?", answer: "Prepare a short symptom history, collect available pathology and imaging reports, list your medicines and allergies, and write down the questions you want to ask. You may also bring a trusted person to help take notes." },
      { question: "Where can I arrange a surgical oncology consultation in Lahore?", answer: "Review the clinic locations listed on Dr. Zain Tayyab Abbas's website and contact the clinic to confirm the current appointment schedule and location before visiting." }
    ],
    sources: [
      {label:"National Cancer Institute – Cancer treatment",url:"https://www.cancer.gov/about-cancer/treatment"},
      {label:"National Cancer Institute – Cancer diagnosis",url:"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis"},
      {label:"American Cancer Society – Getting ready for cancer surgery",url:"https://www.cancer.org/cancer/treatment-types/surgery/getting-ready-for-cancer-surgery.html"},
      {label:"American Cancer Society – Questions to ask about treatment",url:"https://www.cancer.org/cancer/making-treatment-decisions/questions-to-ask-about-treatment.html"}
    ],
    related: ["/specialties/surgical-oncology","/clinics","/contact","/blog/prepare-for-surgical-consultation"]
  },
  "thyroid-nodules-assessment": {
    title: "Thyroid Nodules: A Patient-Friendly Guide to Investigations",
    category: "Endocrine Surgery",
    excerpt: "A patient-friendly guide to thyroid nodule investigations, including thyroid blood tests, ultrasound, fine needle aspiration, biopsy results and follow-up.",
    intro: "Finding a lump in the thyroid can feel worrying, but thyroid nodules are common and more than 9 in 10 are benign (not cancer), according to the British Thyroid Foundation. Some nodules can be felt or seen in the neck, while others are discovered during an examination or scan for another reason. A specialist assessment helps determine which tests are appropriate and whether monitoring or further treatment should be discussed.",
    cover: "/images/thyroid-nodules-patient-guide.png",
    sections: [
      { heading: "Understanding thyroid nodules", paragraphs: ["The thyroid is a small, butterfly-shaped gland at the front of the neck, below the Adam’s apple. A thyroid nodule is a lump or area of tissue within the gland. Nodules may be solid, fluid-filled or have mixed features. Most are non-cancerous, but a newly identified nodule should be assessed by a qualified clinician rather than judged by touch alone.", "The British Thyroid Foundation notes that nodules are more common in women and become more frequent with increasing age. The reason a particular nodule develops is not always known."] },
      { heading: "What happens at the first appointment?", paragraphs: ["A doctor will usually ask about your symptoms and medical history and examine your neck. Tell the clinician when you first noticed the lump, whether it appears to be changing, and whether you have experienced swallowing difficulty, breathing difficulty or a change in your voice. Bring previous thyroid tests and neck imaging if available.", "Your doctor should explain which investigations are recommended, why they are needed and how you will receive the results. Tests may take place at separate appointments; some centres offer a one-stop clinic where several investigations can be arranged during one visit."] },
      { heading: "1. Thyroid blood tests", paragraphs: ["Thyroid function blood tests measure levels of thyroid hormones and related markers to help assess how the gland is working. These tests are commonly part of the initial investigation.", "A thyroid blood test does not test a nodule for cancer. A result within the expected range does not by itself establish whether a nodule is benign or malignant. Your clinician interprets blood results alongside the examination and ultrasound findings."] },
      { heading: "2. Thyroid ultrasound scan", paragraphs: ["An ultrasound scan uses a small probe moved over the skin of the neck to create images of the thyroid and nearby structures. It is painless for most people and does not use ionising radiation. The scan can describe the number and size of nodules, their appearance and relevant features in the surrounding neck, including lymph nodes.", "A specialist sonographer or doctor performs the scan and prepares a formal report. Ultrasound features help the treating team estimate whether a nodule needs sampling or follow-up. The scan does not provide a tissue diagnosis, so additional assessment may be recommended when appropriate."] },
      { heading: "3. Fine needle aspiration (FNA or FNAC)", paragraphs: ["Fine needle aspiration uses a thin needle to collect cells from a thyroid nodule. The sample is examined under a microscope by a laboratory specialist. The procedure is also called fine needle aspiration cytology (FNAC). Local anaesthetic may be used. You may feel pressure or some discomfort in the neck during sampling.", "Not every thyroid nodule needs FNA. The decision depends on the ultrasound appearance, size and individual clinical factors. Sometimes the sample does not contain enough cells to give a clear answer; in that situation, the clinician may recommend another sample or a different next step."] },
      { heading: "4. When might a core biopsy be considered?", paragraphs: ["If an FNA sample does not provide enough information, a clinician may consider a core biopsy. This procedure collects a larger tissue sample using a hollow needle. Local anaesthetic is generally used, and the treating team should explain the reason for the procedure, what to expect and its possible risks before it is performed.", "A core biopsy is not required for every nodule. Your specialist will decide whether it is useful in your particular situation."] },
      { heading: "What should you know after a thyroid biopsy?", paragraphs: ["Some people experience temporary neck discomfort, particularly when swallowing, and bruising around the needle entry site. The British Thyroid Foundation leaflet says these symptoms generally improve quickly; follow the specific aftercare instructions given by the team that performed your biopsy.", "If fluid is aspirated from a fluid-filled nodule, it may collect again over time. Contact your healthcare professional if the area becomes painful or red, or if you are worried about symptoms after the procedure. Seek urgent medical help for severe or rapidly worsening symptoms, including significant breathing difficulty."] },
      { heading: "When will the test results be available?", paragraphs: ["The time needed to prepare results varies by test and service. The British Thyroid Foundation patient leaflet notes that specialist reports may take up to three weeks after the necessary tests have been completed. Your own clinic should tell you when and how results will be communicated.", "If you have not received the results within the timeframe you were given, contact the clinic or the doctor’s secretary rather than assuming that no news means the result is normal. Ask who will explain the findings and what the next appointment or follow-up plan will be."] },
      { heading: "What can the biopsy results mean?", paragraphs: ["A result may indicate that a nodule is benign (not cancer). Sometimes the sample is inadequate or the findings are inconclusive, meaning that the available cells do not allow a confident conclusion. A repeat FNA, additional assessment or, in selected cases, an operation to remove part of the thyroid may be discussed.", "A result may also be suspicious for cancer or show cancerous cells. FNA is helpful but cannot diagnose every thyroid cancer in every situation. Your specialist will explain what the result means in the context of your ultrasound, examination and medical history."] },
      { heading: "What if the result is suspicious or shows cancer?", paragraphs: ["If a biopsy result is suspicious or indicates cancer, your specialist will discuss the findings and the next steps with you. Depending on the diagnosis and individual circumstances, treatment may involve removal of part of the thyroid (hemithyroidectomy or lobectomy) or the whole thyroid (total thyroidectomy). Other investigations or specialist input may also be appropriate.", "The choice of treatment is individual. Ask your clinician to explain the expected benefits, possible risks, alternatives and whether further tests or a multidisciplinary discussion are needed before making a decision."] },
      { heading: "What if the biopsy result is benign?", paragraphs: ["A benign result is reassuring because it means that the sample shows no evidence of cancer. Depending on the ultrasound pattern and the clinical assessment, your doctor may recommend routine follow-up, further ultrasound monitoring or discharge from a specialist clinic. Follow the plan provided for your own case and ask whom to contact if the lump changes or new symptoms appear."] },
      { heading: "Why might a thyroid nodule be monitored?", paragraphs: ["Not every thyroid nodule requires an operation. When surgery is not indicated, a clinician may recommend monitoring, often with a follow-up ultrasound. Monitoring allows the team to review whether the nodule changes over time and whether the original assessment remains reassuring.", "Your doctor should explain why monitoring is recommended, when the next scan is due and what changes would prompt an earlier review. Keep copies of ultrasound reports so that results can be compared over time."] },
      { heading: "Symptoms and changes not to ignore", paragraphs: ["Contact a healthcare professional if you notice a thyroid lump getting bigger or harder, a new lump in the neck, difficulty swallowing, difficulty breathing or persistent hoarseness or a change in your voice. These symptoms do not automatically mean cancer, but they deserve timely assessment.", "If you develop severe or sudden breathing difficulty, seek emergency medical care. Do not wait for a routine appointment when symptoms are urgent."] },
      { heading: "Preparing for your thyroid appointment", paragraphs: ["To make the consultation more useful, organise your records and write down your questions in advance. Bring the thyroid ultrasound report and images, thyroid blood test results, FNA or pathology report if performed, previous neck imaging, specialist letters and a current medicines list. Note when symptoms began and whether they have changed.", "You may wish to ask: What does my ultrasound report show? Do I need FNA? What does my biopsy result mean? When should I expect the result? Is monitoring appropriate? What symptoms should lead me to contact the clinic sooner? If surgery is suggested, what are the alternatives and likely implications?"] },
      { heading: "Thyroid nodule assessment in Lahore", paragraphs: ["Dr. Zain Tayyab Abbas’s website provides information about endocrine surgery consultations in Lahore. A consultation can help review available reports and discuss whether further assessment is appropriate. Explore the [Endocrine Surgery service](/specialties/endocrine-surgery), review [clinic locations](/clinics) or [contact the clinic](/contact) to confirm appointment details."] }
    ],
    faqs: [
      { question: "Are most thyroid nodules cancerous?", answer: "No. The British Thyroid Foundation states that more than 9 in 10 thyroid nodules are benign. However, a newly identified nodule should still be assessed by a qualified clinician." },
      { question: "Can a thyroid blood test tell if a nodule is cancer?", answer: "No. Thyroid blood tests assess thyroid function; they do not test the nodule for cancer. Ultrasound and, when appropriate, a needle sample help assess the nodule." },
      { question: "Does every thyroid nodule need a biopsy?", answer: "No. FNA is recommended only when the ultrasound findings and clinical factors indicate that sampling is appropriate." },
      { question: "Is thyroid ultrasound painful?", answer: "It is usually a painless scan. A small probe is moved over the skin of the neck to examine the thyroid and nearby structures." },
      { question: "What is the difference between FNA and core biopsy?", answer: "FNA collects cells using a thin needle. A core biopsy collects a larger tissue sample using a hollow needle and may be considered when FNA has not provided enough information." },
      { question: "How long do thyroid biopsy results take?", answer: "Timing varies by service. The British Thyroid Foundation leaflet says specialist reports may take up to three weeks after the necessary tests; confirm the expected timeframe with your own clinic." },
      { question: "What happens if the FNA result is inconclusive?", answer: "Your specialist may recommend repeating the FNA, further assessment or another option depending on the ultrasound and clinical findings." },
      { question: "Will a benign thyroid nodule need surgery?", answer: "Not usually. Many benign nodules are monitored or managed without surgery. The appropriate plan depends on symptoms, ultrasound findings and individual circumstances." },
      { question: "What symptoms should prompt an earlier review?", answer: "A growing or harder lump, a new neck lump, difficulty swallowing or breathing, or a persistent change in voice should be discussed promptly with a healthcare professional." },
      { question: "Does a thyroid nodule always cause symptoms?", answer: "No. Some nodules can be felt or seen, while others are found incidentally during an examination or scan for another reason." }
    ],
    sources: [
      {label:"British Thyroid Foundation – Investigating thyroid nodules (patient leaflet)",url:"https://www.btf-thyroid.org/patient-leaflet-about-investigating-thyroid-nodules"},
      {label:"British Thyroid Foundation – Thyroid nodules and swellings",url:"https://www.btf-thyroid.org/thyroid-nodules-and-swellingsleaflet"},
      {label:"NICE – Thyroid disease: assessment and management",url:"https://www.nice.org.uk/guidance/ng145/chapter/recommendations"},
      {label:"NIDDK – Thyroid tests",url:"https://www.niddk.nih.gov/health-information/diagnostic-tests/thyroid"}
    ],
    related: ["/specialties/endocrine-surgery","/specialties/thyroid-cancer-information","/clinics","/contact"]
  },
  "colorectal-consultation-preparation": {
    title: "Preparing for a Colorectal Specialist Appointment",
    category: "Colorectal Health",
    excerpt: "A practical checklist of symptoms, medical history and reports to organise before an appointment.",
    intro: "A colorectal consultation may be arranged for bowel symptoms, an abnormal test, a confirmed diagnosis or a recommendation for a surgical opinion. Organising your history and reports can make the discussion clearer.",
    sections: [
      { heading: "Make a short symptom timeline", paragraphs: ["Write down when the symptoms began, how often they occur and whether they are changing. Include relevant details such as bowel habit changes, abdominal discomfort, bleeding, weight changes or previous episodes. This information does not establish a diagnosis, but it helps the clinician understand the reason for the visit."] },
      { heading: "Collect relevant reports", bullets: ["Colonoscopy or sigmoidoscopy report", "Biopsy or histopathology results", "CT, MRI or other imaging reports and images", "Previous operation notes and discharge summaries", "Recent blood tests and medication list"], paragraphs: ["If you have had a procedure, bring the full report rather than only the appointment summary. If a report is unavailable, tell the clinic which test was performed and where."] },
      { heading: "What may be discussed?", paragraphs: ["The clinician may review the symptoms, examination findings and test results, then explain whether further investigation or another specialist opinion is needed. If a condition requiring surgery is identified, the purpose, possible approaches, risks and recovery considerations should be discussed in relation to the individual case."] },
      { heading: "Questions to ask", paragraphs: [], bullets: ["What do my endoscopy and pathology results show?", "Do I need additional imaging or tests?", "What are the possible management options?", "What symptoms should lead me to seek urgent care?", "When should I expect follow-up?"] }
    ],
    sources: [{label:"NHS – Bowel cancer",url:"https://www.nhs.uk/conditions/bowel-cancer/"}],
    related: ["/specialties/colorectal-cancer-consultation","/specialties/surgical-oncology","/clinics"]
  },
  "when-to-have-a-hernia-assessed": {
    title: "When Should a Hernia Be Assessed by a Surgeon?",
    category: "General Surgery",
    excerpt: "An introduction to common hernia symptoms, clinical assessment and warning signs that need urgent attention.",
    intro: "A hernia occurs when tissue pushes through a weak area in the surrounding muscle or connective tissue. It may appear as a bulge and can cause discomfort, but symptoms and risks vary by hernia type and individual circumstances.",
    sections: [
      { heading: "Common signs and symptoms", paragraphs: ["Some hernias cause a visible or noticeable lump in the groin, abdomen or around a previous surgical scar. The bulge may become more noticeable when standing, coughing or straining. Some people experience dragging discomfort or pain, while others notice few symptoms."] },
      { heading: "How is a hernia assessed?", paragraphs: ["A clinician may ask when the bulge appears, whether it changes with position or activity, and whether there is pain or digestive difficulty. Physical examination is often important. Ultrasound or other imaging may be considered if the diagnosis or anatomy is unclear."] },
      { heading: "When is it urgent?", paragraphs: ["Seek urgent medical assessment if a hernia becomes suddenly or severely painful, the bulge becomes firm or cannot be reduced, or there is vomiting, abdominal swelling, fever, or a change in the skin colour over the lump. These may indicate a complication and should not wait for a routine appointment."] },
      { heading: "What to bring to a consultation", bullets: ["Previous ultrasound or CT reports", "Previous abdominal or hernia operation notes", "Current medicines and allergies", "A note of when the bulge appears and what makes it worse", "Relevant medical conditions"], paragraphs: ["Not every hernia requires immediate surgery. Monitoring or repair may be discussed depending on the hernia type, symptoms, health and clinical findings."] }
    ],
    sources: [{label:"NHS – Hernia",url:"https://www.nhs.uk/conditions/hernia/"},{label:"NIDDK – Inguinal hernia",url:"https://www.niddk.nih.gov/health-information/digestive-diseases/inguinal-hernia"}],
    related: ["/specialties/hernia-information","/specialties/general-surgery","/clinics"]
  },
  "prepare-for-surgical-consultation": {
    title: "What to Bring to Your Consultation",
    category: "Patient Resources",
    excerpt: "A simple checklist to help you organise reports, medicines and questions before meeting a surgeon.",
    intro: "A little preparation can make a surgical appointment more useful. You do not need to have every test completed before asking for advice; bring what you already have and let the clinic guide you about anything missing.",
    sections: [
      { heading: "Bring your medical records", bullets: ["Referral letter, if available", "Previous clinic letters and discharge summaries", "Operation notes, if you have had surgery before", "Relevant blood test results", "Imaging reports and images", "Biopsy or histopathology reports, if performed"], paragraphs: ["For scans, bring both the written report and the image files or access details where possible. A short diagnosis label may not contain all the information the doctor needs."] },
      { heading: "Prepare your medication and health history", paragraphs: ["Make a current list of prescription medicines, over-the-counter products and supplements. Include known allergies and important medical conditions. Do not stop a prescribed medicine before an appointment unless your treating clinician has advised you to do so."] },
      { heading: "Write down your questions", bullets: ["What is the likely explanation for my symptoms or test result?", "Do I need more tests before a decision can be made?", "What options may be suitable for my condition?", "What are the benefits, risks and alternatives?", "What recovery and follow-up might involve?"], paragraphs: ["If you are worried about remembering details, bring a trusted family member or write down the answers, where appropriate."] },
      { heading: "Confirm clinic details before travelling", paragraphs: ["Contact the clinic to confirm the appointment time, location and any specific instructions. Clinic schedules can change, so check before setting out."] }
    ],
    sources: [{label:"NHS – Preparing for an appointment",url:"https://www.nhs.uk/nhs-services/gps/"}],
    related: ["/clinics","/contact","/specialties/surgical-oncology"]
  },

  "breast-self-assessment": {
    title: "Breast Self-Assessment: How to Check Your Breasts and Recognize Early Changes",
    category: "Breast Health",
    excerpt: "Learn breast awareness, recognize unusual changes and understand when to seek a professional breast assessment.",
    intro: "Breast self-awareness means knowing how your breasts normally look and feel so you can notice a new or unusual change. A step-by-step self-check may help you become familiar with your breast tissue, but routine monthly breast self-examination is not recommended as a screening test. It cannot diagnose or rule out breast cancer.",
    cover: "/images/file_0000000001bc8211ab422f0824e461ed.png",
    sections: [
      { heading: "What is breast self-assessment?", paragraphs: ["Breast self-assessment is a way of becoming familiar with the usual appearance and feel of your breasts. You may notice your breasts while bathing, dressing or during an optional, gentle check. The important point is awareness of what is normal for you, rather than following a strict monthly examination schedule.", "Breast self-awareness is different from formal breast self-examination. Routine, repetitive monthly breast self-examination is not recommended for women at average risk as a screening method. Research has not shown that it reduces breast cancer deaths, and false alarms can lead to unnecessary investigations."] },
      { heading: "Why is knowing your normal important?", paragraphs: ["Breast tissue naturally varies. One breast may be slightly larger than the other, and texture can change with hormonal fluctuations, pregnancy, breastfeeding and age. Knowing your usual pattern can help you recognize a change that is new for you.", "A change does not automatically mean cancer. Cysts, fibroadenomas, infections and hormonal changes can also cause breast symptoms. However, a new or persistent change deserves assessment rather than a diagnosis by touch alone."] },
      { heading: "When should you check your breasts?", paragraphs: ["There is no medically required day of the month for routine breast self-examination in women at average risk. You do not need to force a monthly schedule. Instead, stay familiar with your breasts during everyday activities and seek advice when you notice something different.", "If you prefer to use a planned self-check to learn what is normal for you, choose a comfortable time. Breast tenderness and fullness may vary during the menstrual cycle. Do not delay assessment of a new symptom until a particular time in your cycle."] },
      { heading: "How to become familiar with your breasts in 5 steps", paragraphs: ["The following steps are an optional way to learn about your normal breast appearance and feel. They are not a validated screening test, and no particular self-examination technique has been shown to prevent breast cancer deaths. Use gentle pressure and stop if the check causes pain."] },
      { heading: "Step 1: Look at your breasts in a mirror", paragraphs: ["With your upper body uncovered, stand comfortably in front of a mirror with your arms relaxed. Notice the usual size, shape, skin appearance and nipple position of both breasts. A small difference between breasts is common. Look for a new change such as swelling, dimpling, puckering, a persistent rash or a change in nipple position."] },
      { heading: "Step 2: Raise your arms and look again", paragraphs: ["Raise both arms above your head and observe whether you notice a new difference in breast shape, skin or nipple position. You can also place your hands on your hips and gently tighten your chest muscles. Focus on changes from your normal appearance, not on achieving perfect symmetry."] },
      { heading: "Step 3: Notice unexpected nipple discharge", paragraphs: ["Pay attention to fluid that comes from the nipple without squeezing, particularly if it is bloody or clear, comes from one breast, or is new for you. Do not repeatedly squeeze your nipples to check for discharge. New or spontaneous discharge should be discussed with a healthcare professional."] },
      { heading: "Step 4: Become familiar with the feel of your breasts while lying down", paragraphs: ["If you choose to feel your breasts, lie comfortably and use the pads of your three middle fingers with gentle, small circular movements. Become familiar with the breast tissue and the area extending towards the armpit and collarbone. Avoid pressing hard enough to cause pain. You are looking for a new or distinctly different area, not trying to decide whether a lump is cancer."] },
      { heading: "Step 5: Notice changes during everyday activities", paragraphs: ["You may find it easier to notice how your breasts feel while standing or sitting, including during bathing or dressing. There is no need to repeat a detailed examination in multiple positions if it makes you anxious or uncomfortable. The goal is to recognize a change and report it, not to carry out a diagnostic test at home."] },
      { heading: "Normal vs unusual breast changes", paragraphs: ["Breasts naturally vary in size, shape and texture. The comparison below is a general guide to help you notice changes—not a way to diagnose a condition. If a change is new, persistent or concerning, arrange a clinical assessment."], table: { headers: ["Observation", "Can be a normal variation", "Needs medical assessment"], rows: [
        ["Breast size", "One breast has always been slightly larger", "A new or sudden change in size or shape"],
        ["Breast texture", "General lumpiness that varies with the menstrual cycle", "A new, distinct thickened or firm area"],
        ["Breast lump", "A previously assessed, stable benign lump", "Any new lump or a lump that changes"],
        ["Nipple position", "A longstanding natural difference", "A nipple that newly turns inward or changes direction"],
        ["Nipple discharge", "No spontaneous discharge", "Unexpected discharge, especially bloody or clear"],
        ["Breast skin", "Usual skin appearance for you", "New dimpling, puckering, persistent redness or an orange-peel appearance"],
        ["Breast pain", "Mild tenderness that follows a familiar cyclical pattern", "New, persistent or localized pain, especially with another change"]
      ] } },
      { heading: "What breast changes should you not ignore?", paragraphs: ["These symptoms can have non-cancerous causes, but they should be assessed. Breast cancer does not always cause pain, and the absence of pain does not rule it out."], bullets: ["A new lump or thickened area in the breast or armpit", "A new change in breast size, shape or contour", "Skin dimpling, puckering, persistent redness or an orange-peel appearance", "A nipple that newly turns inward or changes position", "Spontaneous nipple discharge, especially if bloody or clear", "A persistent rash, crusting, ulceration or scaling around the nipple", "New, persistent focal breast pain or swelling"] },
      { heading: "What should you do if you notice a lump or change?", paragraphs: ["Arrange an appointment with a qualified healthcare professional or breast specialist. Explain when you first noticed the change, whether it has grown or altered, and whether you have pain, discharge, skin changes or a relevant family history. Avoid repeatedly pressing the area or trying to diagnose it yourself.", "A clinical assessment may include a medical history and examination of the breasts and nearby lymph node areas. Depending on your age, symptoms and findings, the clinician may recommend diagnostic ultrasound, mammography or another imaging test. A biopsy may be considered if an area needs tissue diagnosis. The right tests depend on the individual case.", "For further information, see our [breast lump assessment guide](/blog/breast-lump-assessment), learn about [breast cancer consultation](/specialties/breast-cancer-consultation), or explore [surgical oncology services](/specialties/surgical-oncology)."] },
      { heading: "Are all breast lumps cancerous?", paragraphs: ["No. Many breast lumps are benign. Common causes include fluid-filled cysts, fibroadenomas and hormonal changes. Infection and other benign breast conditions can also cause lumps, swelling or tenderness.", "It is not possible to reliably tell whether a lump is benign or cancerous by its feel alone. A new lump or persistent change should be assessed so the need for imaging or biopsy can be decided appropriately."] },
      { heading: "Does breast self-assessment replace mammography?", paragraphs: ["No. Breast awareness is not a substitute for recommended breast cancer screening. A self-check cannot reliably detect every cancer, and it cannot rule out disease when no lump is felt.", "Screening recommendations differ between countries and may depend on age, personal risk, family history and local guidance. Diagnostic imaging for a new symptom is different from routine screening. Discuss the appropriate screening plan with your healthcare professional, especially if you have a strong family history, a known genetic risk or a previous breast condition."] },
      { heading: "When to seek urgent medical advice", paragraphs: ["Seek prompt medical assessment for a new breast lump, spontaneous bloody nipple discharge, new nipple inversion, skin dimpling or persistent one-sided changes. If you have rapidly worsening breast redness or swelling with fever or feel very unwell, seek urgent medical care because infection or another condition may need prompt treatment."] },
      { heading: "Speak with a breast specialist", paragraphs: ["If you have noticed a breast lump or an unusual change, arrange an individual assessment rather than relying on a home self-check. Find information about [breast cancer consultation in Lahore](/specialties/breast-cancer-consultation) or use the [clinic contact page](/contact) to ask about an appointment."] }
    ],
    faqs: [
      { question: "Is monthly breast self-examination still recommended?", answer: "No. Routine monthly breast self-examination is not recommended as a screening test for women at average risk. Breast self-awareness is encouraged so that you can notice and report new changes." },
      { question: "What is the difference between breast self-awareness and breast self-examination?", answer: "Breast self-awareness means knowing your normal breast appearance and feel without following a required schedule. Formal breast self-examination is a repeated, systematic check, often monthly, and is not recommended as a routine screening method for average-risk women." },
      { question: "What is the best time to check my breasts?", answer: "There is no required monthly time for breast self-awareness. If you choose to do an optional check, choose a comfortable time. Do not postpone assessment of a new change until after your period." },
      { question: "What does a breast cancer lump feel like?", answer: "A concerning lump may feel firm or different from nearby tissue, but breast lumps vary and touch cannot diagnose cancer. Any new lump should be assessed by a healthcare professional." },
      { question: "Are most breast lumps cancerous?", answer: "No. Many breast lumps are benign, including cysts and fibroadenomas. A clinician may recommend imaging or biopsy depending on the examination and individual circumstances." },
      { question: "Can breast cancer occur without pain?", answer: "Yes. Breast cancer may not cause pain, especially early on. Do not wait for pain before seeking assessment of a new lump or other breast change." },
      { question: "Should I squeeze my nipples to check for discharge?", answer: "No. Repeated squeezing is unnecessary. Report discharge that occurs spontaneously, particularly if it is bloody, clear or comes from one breast." },
      { question: "Does a normal self-check mean I do not have breast cancer?", answer: "No. A self-check cannot rule out breast cancer. Follow screening advice appropriate to your age and risk, and seek assessment for any new symptom even if you do not feel a lump." },
      { question: "When should I see a breast specialist?", answer: "Arrange an assessment for a new lump, spontaneous nipple discharge, new nipple inversion, skin dimpling, persistent one-sided changes or another unusual breast symptom. Seek urgent care for rapidly worsening redness or swelling with fever or feeling very unwell." }
    ],
    sources: [
      {label:"American College of Obstetricians and Gynecologists (ACOG) - Monthly breast self-exams",url:"https://www.acog.org/womens-health/experts-and-stories/ask-acog/monthly-self-exams-of-breasts"},
      {label:"Susan G. Komen - Breast self-exam and breast awareness",url:"https://www.komen.org/breast-cancer/screening/breast-self-exam/"},
      {label:"Mayo Clinic - Breast self-exam for breast awareness",url:"https://www.mayoclinic.org/tests-procedures/breast-exam/about/pac-20393237"},
      {label:"NHS - How to check your breasts or chest",url:"https://www.nhs.uk/tests-and-treatments/how-to-check-your-breasts-or-chest/"},
      {label:"Pakistan National Cancer Screening and Early Diagnosis Guidelines",url:"https://www.iccp-portal.org/sites/default/files/2026-04/National_Cancer_Screening_Guidelines_2024_1%20%281%29.pdf"},
    ],
    related: ["/blog/breast-lump-assessment","/specialties/breast-cancer-consultation","/specialties/surgical-oncology","/contact"]
  },
};

export function generateStaticParams() {
  return Object.keys(articles).map((slug) => ({ slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const article = articles[slug];
  if (!article) return { title: "Patient Education Blog" };
  return {
    title: slug === "breast-self-assessment" ? "Breast Self-Assessment: 5-Step Guide | Dr. Zain" : slug === "surgical-oncology-consultation" ? "Surgical Oncology Consultation: What to Expect | Dr. Zain" : slug === "thyroid-nodules-assessment" ? "Thyroid Nodules: Tests, Biopsy & Follow-Up | Dr. Zain" : article.title + " | Patient Education Lahore",
    description: article.excerpt,
    alternates: { canonical: "/blog/" + slug },
    openGraph: { title: article.title, description: article.excerpt, type: "article", images: article.cover ? [{ url: article.cover, alt: article.title }] : undefined },
    twitter: { card: "summary_large_image", title: article.title, description: article.excerpt, images: article.cover ? [article.cover] : undefined }
  };
}

